using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;
public sealed class NWUpgradeProbe:MonoBehaviour {
 [Serializable]class Row{public string name,status,detail;}[Serializable]class Receipt{public string layer,error;public Row[] rows;}public static bool Done;public static int Code;readonly List<Row> rows=new List<Row>();string root;bool ended;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-nw-upgrade")<0)return;var g=new GameObject("NW legacy run transition probe");DontDestroyOnLoad(g);g.AddComponent<NWUpgradeProbe>();}
 void C(string name,bool pass,string detail=""){rows.Add(new Row{name=name,status=pass?"PASS":"FAIL",detail=detail});File.AppendAllText(root+"/progress.jsonl",JsonUtility.ToJson(rows.Last())+"\n");}IEnumerator Wait(Func<bool> cond,float seconds){float end=Time.realtimeSinceStartup+seconds;while(!cond()&&Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Start(){root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool next;object value=null;try{next=stack.Peek().MoveNext();if(next)value=stack.Peek().Current;}catch(Exception e){Finish(e.ToString());yield break;}if(!next){stack.Pop();continue;}if(value is IEnumerator sub){stack.Push(sub);continue;}yield return value;}Finish(null);}
 IEnumerator Run(){yield return Wait(()=>GameEntry.Instance!=null,15);GameEntry.Instance.Refresh();C("old-continue",GameEntry.Instance.Continue());yield return Wait(()=>UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Saves?.IsInitialized==true&&UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.WorldReady==true&&UnityEngine.Object.FindFirstObjectByType<CombatSession>()?.Flow?.ActiveRun!=null,30);var s=UnityEngine.Object.FindFirstObjectByType<CombatSession>();var f=s.Flow;var old=f.ActiveRun;string id=old.runId,profile=f.Profile.profileId,streams=JsonUtility.ToJson(old.randomStreams),tag=old.contentRevision;C("old-flag-not-retrofitted",!NewWeaponDrop.KnownRevision(tag),tag);C("old-factory-disabled",Enumerable.Range(0,100).All(i=>NewWeaponDrop.Preview(old,"legacy-probe-"+i,EnemyArchetype.Elite)==null));C("old-factory-readonly",streams==JsonUtility.ToJson(old.randomStreams));foreach(var e in s.enemies){e.enabled=false;var b=e.GetComponent<ForestBossBrain>();if(b!=null)b.enabled=false;}f.OpenAbandon();C("old-normal-abandon-confirm",f.ConfirmAbandon(),"normal abandonment, not successful extraction or AI adventure");C("old-real-pending",f.Settlement!=null&&f.Settlement.status==SettlementStatus.Pending);C("old-real-commit",f.CommitSettlement());C("old-real-acknowledge",f.AcknowledgeSettlement());C("old-ended-at-camp",f.AtCamp&&f.ActiveRun==null&&f.Profile.profileId==profile);C("new-normal-depart",f.Depart(AdventureMode.ForestExploration),f.DepartureReason);yield return Wait(()=>s.WorldReady&&f.ActiveRun!=null,30);C("new-identity-and-frozen-version",f.ActiveRun!=null&&f.ActiveRun.runId!=id&&f.Profile.profileId==profile&&f.ActiveRun.contentRevision.StartsWith("NWD1:")&&NewWeaponDropRules.Read(f.ActiveRun.contentRevision,out int count)&&count==3);C("new-real-save-v9",s.Saves.SaveProgress(false)&&JsonUtility.FromJson<CombatSaveEnvelope>(File.ReadAllText(s.Saves.SavePath)).version==9);}
 void Finish(string error){if(ended)return;ended=true;if(error!=null)C("upgrade-exception",false,error);Code=rows.Any(x=>x.status=="FAIL")?1:0;File.WriteAllText(root+"/probe.json",JsonUtility.ToJson(new Receipt{layer=Application.isEditor?"controlled Editor old-to-new transition":"nondevelopment Player old-to-new transition",error=error,rows=rows.ToArray()},true));Done=true;if(!Application.isEditor)Application.Quit(Code);}
}
